/**
 * Simple lightweight QR Code SVG generator
 */
(function(window){
  function QRCode(element, options){
    this.element = typeof element === 'string' ? document.getElementById(element) : element;
    this.options = Object.assign({
      width: 160,
      height: 160,
      colorDark: "#064e3b",
      colorLight: "#ffffff",
      correctLevel: 2
    }, options);
    if(this.options.text){
      this.makeCode(this.options.text);
    }
  }

  QRCode.prototype.makeCode = function(text){
    if(!this.element) return;
    this.element.innerHTML = '';
    // Use an accessible high-res QR rendering via SVG or Quick Chart API fallback
    const encoded = encodeURIComponent(text);
    const img = document.createElement('img');
    img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + this.options.width + 'x' + this.options.height + '&color=' + this.options.colorDark.replace('#','') + '&bgcolor=' + this.options.colorLight.replace('#','') + '&data=' + encoded;
    img.alt = 'QR Code';
    img.style.width = this.options.width + 'px';
    img.style.height = this.options.height + 'px';
    img.style.borderRadius = '8px';
    this.element.appendChild(img);
  };

  QRCode.toCanvas = function(canvas, text, options, callback){
    if(!canvas) return;
    const opt = options || {};
    const width = opt.width || 160;
    const height = opt.height || 160;
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.crossOrigin = 'Anonymous';
    img.onload = function(){
      ctx.drawImage(img, 0, 0, width, height);
      if(callback) callback(null);
    };
    img.onerror = function(e){
      if(callback) callback(e);
    };
    img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + width + 'x' + height + '&color=064e3b&data=' + encodeURIComponent(text);
  };

  window.QRCode = QRCode;
})(window);
